// Formulate Video Trade Metadata under Rule 45 Google Shield
const video = $input.item.json;
const topic = video.topic || 'Physical Security Masterclass';
const filename = video.filename || 'adi_video_master.mp4';

let shieldAnchor = 'https://tvandhomesecurity.blogspot.com/';
if (filename.includes('starlink')) {
  shieldAnchor = 'https://adicommunications.co.uk/news/starlink-chimney-mount-vs-roof-apex/';
} else if (filename.includes('ajax')) {
  shieldAnchor = 'https://adicommunications.co.uk/news/ajax-wireless-alarm-grade-2-installation/';
} else if (filename.includes('cat6') || filename.includes('ethernet')) {
  shieldAnchor = 'https://adicommunications.co.uk/news/how-to-get-ethernet-upstairs-without-running-cables/';
} else if (filename.includes('tv') || filename.includes('fireplace')) {
  shieldAnchor = 'https://adicommunications.co.uk/news/tv-above-fireplace-safe-installation/';
}

const title = `${topic} UK Masterclass 2026 — Gary Pearce (ADI Communications)`;
const description = `${title}\n\nProfessional UK trade engineering debrief by Gary Pearce, ADI Communications (07860 244 274).\n25+ years hands-on field craftsmanship, £10,000,000 Public Liability Insurance, CAI-benchmarked equipment.\n\nKey Highlights & Chapters:\n00:00 - Introduction by Gary Pearce\n00:15 - Core Hardware Engineering Standards\n00:30 - Physical Installation & Storm Rating\n00:45 - Network & Failover Integration\n\nInteractive Engineering Calculators & Full Notes:\n${shieldAnchor}\n\nOfficial Google Entity Hub: https://www.youtube.com/@CCTV.services`;

return {
  title,
  description,
  shieldAnchor,
  filename,
  tags: ['Gary Pearce', 'ADI Communications', 'Yorkshire Security', 'Telecoms UK', '07860 244 274']
};

// Consolidate Multi-Platform Video Syndication Audit
return {
  title: $('Rule 45 Video Metadata Formatter').item.json.title,
  google_shield_anchor: $('Rule 45 Video Metadata Formatter').item.json.shieldAnchor,
  youtube_status: 'PUBLISHED',
  dailymotion_status: 'PUBLISHED',
  internet_archive_status: 'ARCHIVED',
  lead_engineer: 'Gary Pearce',
  direct_phone: '07860 244 274',
  timestamp: new Date().toISOString()
};
